def station_folders_to_first_channel(apps, schema_editor):
    """Dotychczasowa para folderów i licznik stanowiska stają się jego pierwszym kanałem (bez BoxingCode)."""
    CycleStation = apps.get_model('ur', 'CycleStation')
    CycleChannel = apps.get_model('ur', 'CycleChannel')
    for station in CycleStation.objects.all():
        CycleChannel.objects.create(
            station=station, watch_dir=station.watch_dir, dest_dir=station.dest_dir,
            max_cycles=station.max_cycles, counter=station.counter, last_cycle_at=station.last_cycle_at,
        )


def first_channel_to_station(apps, schema_editor):
    CycleStation = apps.get_model('ur', 'CycleStation')
    for station in CycleStation.objects.all():
        channel = station.channels.order_by('id').first()
        if channel:
            station.watch_dir, station.dest_dir = channel.watch_dir, channel.dest_dir
            station.max_cycles, station.counter = channel.max_cycles, channel.counter
            station.last_cycle_at = channel.last_cycle_at
            station.save()


